    @Override
    public void setupAnim(Entity entity, float limbSwing, float limbSwingAmount, float ageInTicks, float netHeadYaw, float headPitch) {

        EntityOrch parasite = (EntityOrch)entity;
        this.mainbody.y = 0.0f;
        this.mainbody.xRot = 0.0f;
        this.jointFLLX.yRot = 0.0f;
        this.jointFLLY.xRot = 0.0f;
        this.jointFRLX.yRot = 0.0f;
        this.jointFRLY.xRot = 0.0f;
        this.jointFRL1.xRot = 0.0f;
        this.jointFRL2.xRot = 0.0f;
        this.jointFRL3.xRot = 0.0f;
        this.jointFLL1.xRot = 0.0f;
        this.jointFLL2.xRot = 0.0f;
        this.jointFLL3.xRot = 0.0f;
        this.jointMLLX.yRot = 0.0f;
        this.jointMLLY.xRot = 0.0f;
        this.jointMRLX.yRot = 0.0f;
        this.jointMRLY.xRot = 0.0f;
        this.jointMRL1.xRot = 0.0f;
        this.jointMRL2.xRot = 0.0f;
        this.jointMRL3.xRot = 0.0f;
        this.jointMLL1.xRot = 0.0f;
        this.jointMLL2.xRot = 0.0f;
        this.jointMLL3.xRot = 0.0f;
        this.jointBLLX.yRot = 0.0f;
        this.jointBLLY.xRot = 0.0f;
        this.jointBRLX.yRot = 0.0f;
        this.jointBRLY.xRot = 0.0f;
        this.jointBRL1.xRot = 0.0f;
        this.jointBRL2.xRot = 0.0f;
        this.jointBRL3.xRot = 0.0f;
        this.jointBLL1.xRot = 0.0f;
        this.jointBLL2.xRot = 0.0f;
        this.jointBLL3.xRot = 0.0f;
        this.jointH.xRot = headPitch * 0.016f;
        this.jointH.yRot = netHeadYaw * 0.016f;
        byte i = parasite.getParasiteStatus();
        if (i == 0 || i == 1 || i == 2) {
            if (!parasite.getStillAni()) {
                float GS = 1.5f;
                float GD = 0.5f;
                this.swingY(this.jointFLLX, 0.2f * GS, 0.5f * GD, 1, limbSwing, limbSwingAmount);
                this.swingX(this.jointFLLY, 0.2f * GS, 0.2f * GD, 1, 0.2f, 0.0f, limbSwing, limbSwingAmount);
                this.swingY(this.jointFRLX, 0.2f * GS, 0.5f * GD, 1, limbSwing, limbSwingAmount);
                this.swingX(this.jointFRLY, 0.2f * GS, 0.2f * GD, -1, 0.2f, 0.0f, limbSwing, limbSwingAmount);
                this.swingX(this.jointFRL1, 0.2f * GS, 0.5f * GD, -1, 1.0f, 0.0f, limbSwing, limbSwingAmount);
                this.swingX(this.jointFRL2, 0.2f * GS, 0.5f * GD, -1, 1.0f, 0.2f, limbSwing, limbSwingAmount);
                this.swingX(this.jointFRL3, 0.2f * GS, 0.5f * GD, -1, 1.0f, 0.0f, limbSwing, limbSwingAmount);
                this.swingX(this.jointFLL1, 0.2f * GS, 0.5f * GD, 1, 1.0f, 0.0f, limbSwing, limbSwingAmount);
                this.swingX(this.jointFLL2, 0.2f * GS, 0.5f * GD, 1, 1.0f, 0.2f, limbSwing, limbSwingAmount);
                this.swingX(this.jointFLL3, 0.2f * GS, 0.5f * GD, 1, 1.0f, 0.0f, limbSwing, limbSwingAmount);
                this.swingY(this.jointMLLX, 0.2f * GS, 0.8f * GD, -1, limbSwing, limbSwingAmount);
                this.swingX(this.jointMLLY, 0.2f * GS, 0.2f * GD, -1, 1.0f, 0.0f, limbSwing, limbSwingAmount);
                this.swingY(this.jointMRLX, 0.2f * GS, 0.8f * GD, -1, limbSwing, limbSwingAmount);
                this.swingX(this.jointMRLY, 0.2f * GS, 0.2f * GD, 1, 2.0f, 0.0f, limbSwing, limbSwingAmount);
                this.swingX(this.jointMRL1, 0.2f * GS, 0.5f * GD, 1, 1.0f, 0.0f, limbSwing, limbSwingAmount);
                this.swingX(this.jointMRL2, 0.2f * GS, 0.5f * GD, 1, 1.0f, 0.2f, limbSwing, limbSwingAmount);
                this.swingX(this.jointMRL3, 0.2f * GS, 0.5f * GD, 1, 1.0f, 0.0f, limbSwing, limbSwingAmount);
                this.swingX(this.jointMLL1, 0.2f * GS, 0.5f * GD, -1, 1.0f, 0.0f, limbSwing, limbSwingAmount);
                this.swingX(this.jointMLL2, 0.2f * GS, 0.5f * GD, -1, 1.0f, 0.2f, limbSwing, limbSwingAmount);
                this.swingX(this.jointMLL3, 0.2f * GS, 0.5f * GD, -1, 1.0f, 0.0f, limbSwing, limbSwingAmount);
                this.swingY(this.jointBLLX, 0.2f * GS, 0.5f * GD, 1, limbSwing, limbSwingAmount);
                this.swingX(this.jointBLLY, 0.2f * GS, 0.2f * GD, 1, 1.0f, 0.0f, limbSwing, limbSwingAmount);
                this.swingY(this.jointBRLX, 0.2f * GS, 0.5f * GD, 1, limbSwing, limbSwingAmount);
                this.swingX(this.jointBRLY, 0.2f * GS, 0.2f * GD, -1, 2.0f, 0.0f, limbSwing, limbSwingAmount);
                this.swingX(this.jointBRL1, 0.2f * GS, 0.5f * GD, -1, 1.0f, 0.0f, limbSwing, limbSwingAmount);
                this.swingX(this.jointBRL2, 0.2f * GS, 0.5f * GD, -1, 1.0f, 0.2f, limbSwing, limbSwingAmount);
                this.swingX(this.jointBRL3, 0.2f * GS, 0.5f * GD, -1, 1.0f, 0.0f, limbSwing, limbSwingAmount);
                this.swingX(this.jointBLL1, 0.2f * GS, 0.5f * GD, 1, 1.0f, 0.0f, limbSwing, limbSwingAmount);
                this.swingX(this.jointBLL2, 0.2f * GS, 0.5f * GD, 1, 1.0f, 0.2f, limbSwing, limbSwingAmount);
                this.swingX(this.jointBLL3, 0.2f * GS, 0.5f * GD, 1, 1.0f, 0.0f, limbSwing, limbSwingAmount);
                this.moveY(this.mainbody, 0.4f * GS, 1, limbSwing, limbSwingAmount, 0.09f);
            }
            float f1 = Mth.cos((float)(ageInTicks * 0.16f)) * 0.219f;
            float f2 = Mth.cos((float)(ageInTicks * 0.18f)) * 0.23f;
            float f3 = Mth.cos((float)(ageInTicks * 0.17f)) * 0.22f;
            this.hair_jointRR1.xRot = f1;
            this.hair_jointRR3.xRot = f2;
            this.hair_jointRR5.xRot = f3;
            this.hair_jointR1.xRot = f2;
            this.hair_jointR3.xRot = f3;
            this.hair_jointR5.xRot = f1;
            this.hair_jointLL1.xRot = f1 *= -1.0f;
            this.hair_jointLL3.xRot = f3 *= -1.0f;
            this.hair_jointLL5.xRot = f2 *= -1.0f;
            this.hair_jointL1.xRot = f3;
            this.hair_jointL3.xRot = f2;
            this.hair_jointL5.xRot = f1;
            this.jointT.xRot = f1 = 0.1f + Mth.cos((float)(ageInTicks * 0.116f)) * 0.119f;
            this.jointT_1.xRot = f1;
            this.jointT_3.xRot = f1;
            this.jointT_5.xRot = f1;
        } else if (i == 10) {
            float f1 = Mth.cos((float)(ageInTicks * 0.16f)) * 0.3119f;
            float f2 = Mth.cos((float)(ageInTicks * 0.18f)) * 0.313f;
            float f3 = Mth.cos((float)(ageInTicks * 0.17f)) * 0.312f;
            this.hair_jointRR1.xRot = f1;
            this.hair_jointRR3.xRot = f2;
            this.hair_jointRR5.xRot = f3;
            this.hair_jointR1.xRot = f2;
            this.hair_jointR3.xRot = f3;
            this.hair_jointR5.xRot = f1;
            this.hair_jointLL1.xRot = f1 *= -1.0f;
            this.hair_jointLL3.xRot = f3 *= -1.0f;
            this.hair_jointLL5.xRot = f2 *= -1.0f;
            this.hair_jointL1.xRot = f3;
            this.hair_jointL3.xRot = f2;
            this.hair_jointL5.xRot = f1;
            f1 = 0.1f + Mth.cos((float)(ageInTicks * 0.2716f)) * 0.119f;
            this.jointT.xRot = -1.1f + f1;
            this.jointT_1.xRot = -0.5f + f1;
            this.jointT_3.xRot = 1.5f + f1;
            this.jointT_5.xRot = 1.5f + f1;
            this.mainbody.xRot = -0.7f;
            f1 = Mth.cos((float)(ageInTicks * 0.2116f)) * 0.119f;
            f2 = -Mth.cos((float)(ageInTicks * 0.25116f)) * 0.1519f;
            this.jointFLLX.yRot = 0.0f;
            this.jointFLLY.xRot = 0.5f + f1;
            this.jointFRLX.yRot = 0.0f;
            this.jointFRLY.xRot = 0.5f + -1.0f * f1;
            this.jointFRL1.xRot = 0.5f + -1.0f * f1;
            this.jointFRL2.xRot = -1.0f * f1;
            this.jointFRL3.xRot = -1.0f * f1;
            this.jointFLL1.xRot = 0.5f + f1;
            this.jointFLL2.xRot = f1;
            this.jointFLL3.xRot = f1;
            this.jointMLLX.yRot = 0.0f;
            this.jointMLLY.xRot = 0.9f + f2;
            this.jointMRLX.yRot = 0.0f;
            this.jointMRLY.xRot = 0.9f + -1.0f * f2;
            this.jointMRL1.xRot = 0.2f + -f2;
            this.jointMRL2.xRot = -f2;
            this.jointMRL3.xRot = -f2;
            this.jointMLL1.xRot = 0.2f + f2;
            this.jointMLL2.xRot = f2;
            this.jointMLL3.xRot = f2;
            this.jointBLLX.yRot = 0.0f;
            this.jointBLLY.xRot = 1.0f + -f1;
            this.jointBRLX.yRot = 0.0f;
            this.jointBRLY.xRot = 1.0f + f1;
            this.jointBRL1.xRot = -0.2f + f1;
            this.jointBRL2.xRot = f1;
            this.jointBRL3.xRot = f1;
            this.jointBLL1.xRot = -0.2f + -f1;
            this.jointBLL2.xRot = -f1;
            this.jointBLL3.xRot = -f1;
        }
        this.underground(parasite, ageInTicks, this.mainbody);
    
    }

